function shuffle(a) {
  const b = [...a];
  for (let i = b.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [b[i], b[j]] = [b[j], b[i]];
  }
  return b;
}

const QUESTION_BANK = BLUEPRINTS.map((b, idx) => {
  const options = shuffle([b[3], ...b[4]]);
  return {
    id: idx + 1,
    topic: b[0],
    concept: b[1],
    question: b[2],
    options,
    answer: options.indexOf(b[3]),
    explanation: b[5],
    tip: `Palavra-chave: ${b[1]}. Identifique primeiro a habilidade e o recurso ou configuração correspondente.`
  };
});
